window.__PAGES=window.__PAGES||{};window.__PAGES["pages/broadcast-draft.html"]="<!-- Broadcast Draft — list of drafts -->\n<div class=\"broadcast-layout\">\n  <aside class=\"broadcast-sidenav\">\n    <div class=\"sn-title\">Broadcast Massal</div>\n    <div class=\"sn-item\" onclick=\"go('broadcast/messages')\">📢 Pesan</div>\n    <div class=\"sn-item active\" onclick=\"go('broadcast/draft')\">📝 Draft</div>\n    <div class=\"sn-item\" onclick=\"go('broadcast/templates')\">📋 Template</div>\n  </aside>\n  <div class=\"broadcast-body\">\n    <div class=\"page-header\">\n      <h1>Draft Broadcast</h1>\n    </div>\n    <div class=\"page-body\" id=\"draftList\"></div>\n  </div>\n</div>\n\n<script>\nfunction renderDrafts(){\n  const el=document.getElementById('draftList');\n  const drafts=DB.broadcastDrafts;\n  if(!drafts.length){\n    el.innerHTML='<div style=\"text-align:center;color:var(--muted);padding:60px 0\"><div style=\"font-size:40px;opacity:.4;margin-bottom:8px\">📝</div><b>Belum ada draft</b><p style=\"font-size:13px;margin-top:4px\">Buat broadcast baru dari halaman Pesan untuk memulai.</p></div>';\n    return;\n  }\n  el.innerHTML=drafts.map(d=>{\n    const tpl=DB.templates.find(t=>t.id===d.templateId);\n    return `<div class=\"card\" style=\"display:flex;align-items:center;gap:16px\">\n      <div style=\"flex:1;min-width:0\">\n        <b>${d.name}</b>\n        <div style=\"font-size:12px;color:var(--muted);margin-top:2px\">Template: ${tpl?tpl.name:'-'} · Penerima: ${d.recipients||0}</div>\n      </div>\n      <button class=\"btn\" onclick=\"editDraft('${d.id}')\" style=\"font-size:12px\">✏️ Edit</button>\n      <button class=\"btn danger\" onclick=\"delDraft('${d.id}')\" style=\"font-size:12px\">🗑 Hapus</button>\n    </div>`;\n  }).join('');\n}\n\nfunction editDraft(id){\n  // ponytail: reuse broadcast modal on messages page\n  go('broadcast/messages');\n  showToast('Edit draft: buka dari halaman Pesan');\n}\n\nfunction delDraft(id){\n  dbRemove('broadcastDrafts',id);\n  renderDrafts();\n  showToast('Draft dihapus');\n}\n\nrenderDrafts();\n</script>\n";
